let done = new Set();
const STORAGE_KEY = 'ex751-plan-done-ids';
let storageOK = true; // flips false if localStorage isn't usable — falls back to in-memory only

function loadDone() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) done = new Set(JSON.parse(raw));
  } catch (e) {
    storageOK = false; // private/incognito mode with storage disabled, or similar
  }
}

function saveDone() {
  if (!storageOK) return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify([...done]));
  } catch (e) {
    storageOK = false; // quota exceeded or storage blocked mid-session
    render();
  }
}

function renderSaveWarning() {
  const prog = document.getElementById('prog');
  if (!prog.querySelector('.save-warn')) {
    const warn = document.createElement('span');
    warn.className = 'save-warn';
    warn.style.cssText = 'color: var(--repeat); margin-left: 10px; font-size: 11px;';
    warn.textContent = '· not saving (progress will reset on reload)';
    prog.appendChild(warn);
  }
}

function render() {
  const container = document.getElementById('blocks');
  container.innerHTML = '';
  let totalItems = 0, doneItems = 0;

  blocks.forEach((b, bi) => {
    if (b.items.length === 0) {
      const div = document.createElement('div');
      div.style.cssText = "margin: 4px 0 16px; padding-left: 8px; border-left: 2px solid var(--border); font-size: 12px; color: var(--text-muted);";
      div.textContent = b.time + " — " + b.label;
      container.appendChild(div);
      return;
