    const wrap = document.createElement('div');
    wrap.style.cssText = "margin-bottom: 20px; padding: 12px 14px; background: var(--surface-1); border-radius: var(--radius);";

    const head = document.createElement('div');
    head.style.cssText = "display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px;";
    head.innerHTML = '<span style="font-weight: 500; font-size: 14px;">' + b.time + ' · ' + b.label + '</span><span style="font-size: 11px; color: var(--text-muted); text-align: right;">' + (b.marks ? b.marks : '') + '</span>';
    wrap.appendChild(head);

    b.items.forEach((item, ii) => {
      totalItems++;
      const id = bi + '-' + ii;
      if (done.has(id)) doneItems++;
      const row = document.createElement('label');
      row.style.cssText = "display: flex; align-items: flex-start; gap: 8px; padding: 4px 0; cursor: pointer; font-size: 13px;";
